// V4.1: Kartenwerte neu – Bronze 101–110, Silber 111–120, Gold 121–135 (eigene Spieler höchstens 110)
(function(){ const M = { bronze: [86, 99, 101, 110], silber: [100, 118, 111, 120], gold: [121, 140, 121, 135] };
  PLAYER_DATABASE.forEach(p => { const m = p.stufe && M[p.stufe]; if (m){ const r = Math.min(m[1], Math.max(m[0], +p.rating || m[0])); p.rating = Math.round(m[2] + (r - m[0]) * (m[3] - m[2]) / Math.max(1, m[1] - m[0])); } }); })();